  '.markdown',
  '.mdown',
  '.mkdn',
  '.mkd',
  '.mdwn',
  '.mkdown',
  '.ron',
];

function isMDFormat(filepath: string) {
  return mdFormatExtensions.includes(path.extname(filepath));
}

