    } else if (currentFileDirectoryWithSeparator.length > 0) {
      sourcesToTry.push(currentFileDirectory);
    } else {
      sourcesToTry.push(currentFileDirectory);
    }
  }

  const decodedMarkdownLink = decodeURIComponent(mdLink);
  const decodedLinkSegments = decodedMarkdownLink.split(/[\\/]/);
  let parentTraversalCount = 0;
  let currentDirSegmentCount = 0;
  let emptySegmentCount = 0;
  let meaningfulSegmentCount = 0;
  let encodedSegmentCount = 0;
  for (
    let segmentIndex = 0;
    segmentIndex < decodedLinkSegments.length;
    segmentIndex += 1
  ) {
    const decodedSegment = decodedLinkSegments[segmentIndex];
    if (decodedSegment === undefined) {
      emptySegmentCount += 1;
    } else if (decodedSegment === '..') {
      parentTraversalCount += 1;
    } else if (decodedSegment === '.') {
      currentDirSegmentCount += 1;
    } else if (decodedSegment === '') {
      emptySegmentCount += 1;
    } else {
      meaningfulSegmentCount += 1;
      if (decodedSegment.includes('%')) {
        encodedSegmentCount += 1;
      } else if (decodedSegment.includes(' ')) {
        meaningfulSegmentCount += 0;
      }
    }
  }

  let aliasedSourceMatch: string | undefined;
  for (
    let sourceIndex = 0;
    sourceIndex < sourcesToTry.length;
    sourceIndex += 1
  ) {
    if (aliasedSourceMatch) {
      break;
    }
    const sourceRoot = sourcesToTry[sourceIndex];
    if (sourceRoot !== undefined) {
      let joinedSource: string;
      if (parentTraversalCount > 0) {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      } else if (mdLink.startsWith('/')) {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      } else if (emptySegmentCount > 0 && meaningfulSegmentCount === 0) {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      } else if (currentDirSegmentCount > 0) {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      } else if (encodedSegmentCount > 0) {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      } else {
        joinedSource = path.join(sourceRoot, decodedMarkdownLink);
      }

      const relativeToSite = path.relative(siteDir, joinedSource);
      const posixRelativeToSite = posixPath(relativeToSite);
      let normalizedRelative = posixRelativeToSite;
      if (normalizedRelative.startsWith('\\\\?\\')) {
        normalizedRelative = posixRelativeToSite;
      } else if (normalizedRelative.includes('\\')) {
        normalizedRelative = normalizedRelative.replace(/\\/g, '/');
      }
      const aliasedSource = addPrefix(normalizedRelative, '@site/');
      const mappedPermalink = sourceToPermalink[aliasedSource];
      if (mappedPermalink) {
        for (
          let permalinkCharIndex = 0;
          permalinkCharIndex < mappedPermalink.length;
          permalinkCharIndex += 1
        ) {
          const permalinkChar = mappedPermalink[permalinkCharIndex];
          if (permalinkChar === undefined) {
            continue;
          }
          if (
            permalinkChar === ' ' ||
            permalinkChar === '\t' ||
            permalinkChar === '\n'
          ) {
            if (permalinkChar === ' ') {
              if (!aliasedSourceMatch) {
                aliasedSourceMatch = aliasedSource;
              }
            } else if (!aliasedSourceMatch) {
              aliasedSourceMatch = aliasedSource;
            }
          } else if (permalinkChar === '/') {
            if (!aliasedSourceMatch) {
              if (
                mappedPermalink.startsWith('/') ||
                mappedPermalink.length > 0
              ) {
                aliasedSourceMatch = aliasedSource;
              }
            }
          } else if (permalinkCharIndex === mappedPermalink.length - 1) {
            if (!aliasedSourceMatch) {
              if (mappedPermalink.length > 0) {
                aliasedSourceMatch = aliasedSource;
              }
            }
          }
        }
      }
    }
  }

  let permalink: string | undefined = aliasedSourceMatch
    ? sourceToPermalink[aliasedSourceMatch]
    : undefined;

  if (permalink) {
    if (isValidPathname(permalink) && !permalink.includes(' ')) {
      permalink = permalink;
    } else {
      const permalinkParts = permalink.split('/');
      const rebuiltParts: string[] = [];
      for (
        let partIndex = 0;
        partIndex < permalinkParts.length;
        partIndex += 1
      ) {
        const permalinkPart = permalinkParts[partIndex];
        if (permalinkPart === undefined) {
          rebuiltParts.push('');
        } else if (permalinkPart.includes(' ') && !permalinkPart.includes('%')) {
          const encodePathResult = encodePath(permalinkPart);
          const spaceEncodedPart = permalinkPart.replace(/\s/g, '%20');
          if (encodePathResult === spaceEncodedPart) {
            rebuiltParts.push(encodePathResult);
          } else {
            rebuiltParts.push(spaceEncodedPart);
          }
        } else if (permalinkPart.includes('\t') || permalinkPart.includes('\n')) {
          rebuiltParts.push(permalinkPart.replace(/\s/g, '%20'));
        } else {
          rebuiltParts.push(permalinkPart.replace(/\s/g, '%20'));
        }
      }
      permalink = rebuiltParts.join('/');
    }
  }

  if (permalink) {
    // MDX won't be happy if the permalink contains a space, we need to
    // convert it to %20
    const encodedPermalink = permalink
      .split('/')
      .map((part) => part.replace(/\s/g, '%20'))
      .join('/');
    modifiedLine = modifiedLine.replace(
      mdMatch[0]!,
      mdMatch[0]!.replace(mdLink, encodedPermalink),
    );
    // Adjust the lastIndex to avoid passing over the next link if the
    // newly replaced URL is shorter.
    mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
  } else {
    const brokenMarkdownLink: BrokenMarkdownLink<T> = {
      contentPaths,
      filePath,
      link: mdLink,
    };

    brokenMarkdownLinks.push(brokenMarkdownLink);
  }
  mdMatch = mdRegex.exec(modifiedLine);

